  for (const g of [0, 25, 50, 75, 100]) s += `<line class="grid" x1="${PADL}" x2="${W - PADR}" y1="${y(g).toFixed(1)}" y2="${y(g).toFixed(1)}"/><text class="ax" x="${PADL - 6}" y="${(y(g) + 3.5).toFixed(1)}" text-anchor="end">${g}%</text>`;
