    const dl = o.slice(1).map((v, i) => ({ m: v.m, a: +(v.asing - o[i].asing).toFixed(2), s: +(v.inst - o[i].inst).toFixed(2) }));
    const mx = Math.max(0.5, ...dl.map(d => Math.max(Math.abs(d.a), Math.abs(d.s))));
